mapper.select:
SELECT dept_name AS deptName, MAX(avg_usage) AS avgUsage, MAX(am_usage) AS amUsage, MAX(pm_usage) AS pmUsage, MAX(holiday_usage) AS holidayUsage FROM TR_ROOM_USE_DTL WHERE stat_date BETWEEN #{startDate} AND #{endDate}
AND dept_name LIKE '%' || #{deptName} || '%'
GROUP BY dept_name ORDER BY dept_name
